@field_validator('version')
@classmethod
def _check_version(cls, v: int) -> int:
    if v != 1:
        msg = f'Unsupported config version: {v}. Only version 1 is supported.'
        raise ValueError(msg)
    return v

def find_config(root: str) -> Path | None:
    root_path = Path(root).resolve()
    candidates = [root_path / 'codegraph.jsonc', root_path / 'codegraph.json']
    for p in candidates:
        if p.exists():
            return p
    return None

def _strip_jsonc_comments(text: str) -> str:
    lines: list[str] = []
    for line in text.split('\n'):
        stripped = line.strip()
        if stripped.startswith('//'):
            continue
        if '//' in line:
            in_string = False
            chars: list[str] = []
            i = 0
            while i < len(line):
                c = line[i]
                if c == '"' and (i == 0 or line[i - 1] != '\\'):
                    in_string = not in_string
                if c == '/' and i + 1 < len(line) and (line[i + 1] == '/') and (not in_string):
                    break
                chars.append(c)
                i += 1
            lines.append(''.join(chars))
        else:
            lines.append(line)
    return '\n'.join(lines)

def load_config(root: str) -> CodegraphConfig:
    config_path = find_config(root)
    if config_path is None:
        return CodegraphConfig()
    raw = config_path.read_text()
    stripped = _strip_jsonc_comments(raw)
    try:
        data: dict[str, Any] = json.loads(stripped)
    except json.JSONDecodeError as e:
        msg = f'Invalid config file {config_path}: {e}'
        raise ValueError(msg) from e
    return CodegraphConfig(**data)

def _detect_language_and_type(dir_path: Path) -> tuple[str, str] | None:
    has_go_mod = (dir_path / 'go.mod').exists()
    has_package_json = (dir_path / 'package.json').exists()
    has_pyproject = (dir_path / 'pyproject.toml').exists()
    has_setup = (dir_path / 'setup.py').exists()
    has_requirements = (dir_path / 'requirements.txt').exists()
    has_cargo = (dir_path / 'Cargo.toml').exists()
    has_pom = (dir_path / 'pom.xml').exists()
    has_gradle = (dir_path / 'build.gradle').exists()
    if has_go_mod:
        has_main = (dir_path / 'main.go').exists() or (dir_path / 'cmd').is_dir()
        return ('go', 'service' if has_main else 'library')
    if has_package_json:
        content = _try_read_json(dir_path / 'package.json')
        has_next = False
        if content and isinstance(content, dict):
            deps = {**(content.get('dependencies') or {}), **(content.get('devDependencies') or {})}
            has_next = 'next' in deps or any(('next' in str(k) for k in deps))
        return ('typescript', 'frontend' if has_next else 'library')
    if has_pyproject or has_setup or has_requirements:
        return ('python', 'library')
    if has_cargo:
        return ('rust', 'library')
    if has_pom or has_gradle:
        return ('java', 'library')
    return None

def _try_read_json(path: Path) -> Any | None:
    try:
        import json
        return json.loads(path.read_text())
    except (OSError, json.JSONDecodeError, ValueError):
        return None

def _detect_type_override(dir_path: Path, language: str) -> str:
    if language != 'python':
        return 'library'
    try:
        source_files = list(dir_path.rglob('*.py'))
        content = ''
        for f in source_files[:50]:
            try:
                content += f.read_text(errors='replace') + '\n'
            except OSError:
                continue
        has_flask = '@app.route' in content or 'Flask(' in content
        has_fastapi = '@app.get' in content or '@app.post' in content or 'FastAPI(' in content
        has_django = 'django' in content.lower() and ('urlpatterns' in content or 'wsgi' in content)
        has_manage = (dir_path / 'manage.py').exists()
        if has_fastapi or has_flask or has_django or has_manage:
            return 'service'
        if (dir_path / 'wsgi.py').exists() or (dir_path / 'asgi.py').exists():
            return 'service'
    except (OSError, UnicodeDecodeError):
        pass
    return 'library'

def auto_discover(root: str) -> list[WorkspaceEntry]:
    root_path = Path(root).resolve()
    entries: list[WorkspaceEntry] = []
    skip_dirs = {'.git', '.codegraph', '.gograph', '.tsgraph', '.pygraph', '__pycache__', 'node_modules', 'venv', '.venv', '.env', 'target', 'build', 'dist', '.egg-info'}
    try:
        items = sorted(root_path.iterdir())
    except OSError:
        return entries
    for item in items:
        if not item.is_dir():
            continue
        if item.name.startswith('.'):
            continue
        if item.name in skip_dirs:
            continue
        detected = _detect_language_and_type(item)
        if detected is None:
            continue
        language, detected_type = detected
        if language == 'python' and detected_type == 'library':
            detected_type = _detect_type_override(item, language)
        is_built = language in BUILT_LANGUAGES
        entries.append(WorkspaceEntry(name=item.name, language=language, type=detected_type, path=str(item.relative_to(root_path)), build_status='unbuilt' if is_built else 'unsupported'))
    return entries

def resolve_entries(config: CodegraphConfig, root: str) -> list[WorkspaceEntry]:
    if not config.auto_discover and (not config.entries):
        return []
    if config.auto_discover:
        discovered = auto_discover(root)
        explicit_map: dict[str, EntryConfig] = {}
        for e in config.entries:
            explicit_map[e.name] = e
        merged: dict[str, WorkspaceEntry] = {}
        for d in discovered:
            merged[d.name] = d
        for name, ec in explicit_map.items():
            if name in merged:
                merged[name].type = ec.type
            else:
                is_built = ec.language in BUILT_LANGUAGES
                merged[name] = WorkspaceEntry(name=ec.name, language=ec.language, type=ec.type, path=ec.path, build_status='unbuilt' if is_built else 'unsupported')
        entries = list(merged.values())
    else:
        entries = []
        for ec in config.entries:
            is_built = ec.language in BUILT_LANGUAGES
            entries.append(WorkspaceEntry(name=ec.name, language=ec.language, type=ec.type, path=ec.path, build_status='unbuilt' if is_built else 'unsupported'))
    path_map: dict[str, list[str]] = {}
    for ent in entries:
        path_map.setdefault(ent.path, []).append(ent.name)
    for path, entry_names in path_map.items():
        if len(entry_names) > 1:
            print(f"  Warning: entries {entry_names} share the same path '{path}'")
    return entries

def _build_cmd(tool: str, entry_path: Path) -> list[str]:
    if tool in ('gograph', 'tsgraph'):
        return [tool, 'build', str(entry_path)]
    return [tool, 'build', '--root', str(entry_path)]

def _run_tool_build(entry: WorkspaceEntry, root_path: Path) -> WorkspaceEntry:
    tool = TOOL_BY_LANGUAGE.get(entry.language)
    if tool is None:
        entry.build_status = 'unsupported'
        return entry
    entry_path = root_path / entry.path
    if not entry_path.is_dir():
        entry.build_status = 'failed'
        return entry
    start = time.monotonic()
    try:
        result = subprocess.run(_build_cmd(tool, entry_path), capture_output=True, text=True, timeout=120, cwd=str(entry_path))
        elapsed = int((time.monotonic() - start) * 1000)
        entry.build_duration_ms = elapsed
        if result.returncode != 0:
            entry.build_status = 'failed'
            if result.stderr:
                print(f'  [{entry.name}] stderr:', result.stderr.strip(), flush=True)
            return entry
        entry.build_status = 'ok'
        try:
            version_result = subprocess.run([tool, '--version'], capture_output=True, text=True, timeout=10)
            ver = version_result.stdout.strip() if version_result.returncode == 0 else ''
            entry.tool_version = ver
        except (OSError, subprocess.SubprocessError, subprocess.TimeoutExpired):
            entry.tool_version = ''
    except (OSError, subprocess.TimeoutExpired, subprocess.SubprocessError):
        entry.build_status = 'failed'
    return entry

def _prefix_ids(items: list[dict[str, Any]], prefix: str, id_fields: set[str]) -> None:
    for item in items:
        for field in id_fields:
            if field in item and isinstance(item[field], str):
                item[field] = f'{prefix}::{item[field]}'

def _build_single(entry: WorkspaceEntry, root_path: Path) -> None:
    if entry.language not in BUILT_LANGUAGES:
        entry.build_status = 'unsupported'
        return
    _run_tool_build(entry, root_path)

def build_entry(entry: WorkspaceEntry, root_path: Path) -> WorkspaceEntry:
    result = _run_tool_build(entry, root_path)
    return result

def _build_one(entry: WorkspaceEntry, root_path: Path) -> WorkspaceEntry:
    if entry.language not in BUILT_LANGUAGES:
        entry.build_status = 'unsupported'
        return entry
    start = time.monotonic()
    print(f'  [{entry.name}] building ({entry.language})...', flush=True)
    entry = _run_tool_build(entry, root_path)
    elapsed = time.monotonic() - start
    if entry.build_status == 'ok':
        print(f'  [{entry.name}] done ({elapsed:.1f}s)', flush=True)
    elif entry.build_status == 'failed':
        print(f'  [{entry.name}] FAILED ({elapsed:.1f}s)', flush=True)
    else:
        print(f'  [{entry.name}] {entry.build_status}', flush=True)
    return entry

def build_all(root: str, entries: list[WorkspaceEntry] | None=None, max_workers: int=4) -> UnifiedGraph:
    root_path = Path(root).resolve()
    config = load_config(root)
    if entries is None:
        entries = resolve_entries(config, root)
    unified = make_unified_graph(workspace_root=str(root_path))
    buildable = [e for e in entries if e.language in BUILT_LANGUAGES]
    skipped = [e for e in entries if e.language not in BUILT_LANGUAGES]
    for e in skipped:
        e.build_status = 'unsupported'
        if unified.manifest is not None:
            unified.manifest.entries.append(e)
    print(f'Building {len(buildable)} entries ({len(skipped)} skipped)...')
    overall_start = time.monotonic()
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as pool:
        futures = {pool.submit(_build_one, entry, root_path): entry for entry in buildable}
        for future in concurrent.futures.as_completed(futures):
            entry = futures[future]
            try:
                result = future.result()
            except Exception as exc:
                print(f'  [{entry.name}] ERROR: {exc}', flush=True)
                result = entry
                result.build_status = 'failed'
            if result.build_status == 'ok':
                _stamp_and_collect(result, root_path, unified)
            if unified.manifest is not None:
                unified.manifest.entries.append(result)
    total_time = time.monotonic() - overall_start
    ok_count = sum((1 for e in buildable if e.build_status == 'ok'))
    fail_count = sum((1 for e in buildable if e.build_status == 'failed'))
    print(f'Built {ok_count}/{len(buildable)} entries ({fail_count} failed) in {total_time:.1f}s')
    return unified

def _find_nearest_graph(root: str) -> Path | None:
    path = Path(root).resolve()
    for parent in [path] + list(path.parents):
        candidate = parent / '.codegraph' / 'workspace.graph.json'
        if candidate.exists():
            return candidate
    return None

def _load_query(root: str) -> WorkspaceQuery:
    graph_path = Path(root) / '.codegraph' / 'workspace.graph.json'
    if not graph_path.exists():
        nearest = _find_nearest_graph(root)
        if nearest:
            typer.echo(f"Error: no graph found at {graph_path}.\nFound one at {nearest} — did you mean '--root {nearest.parent.parent}'?")
        else:
            typer.echo(f"Error: no graph found at {graph_path}.\nRun 'codegraph build' in your workspace root first.")
        raise typer.Exit(1)
    graph = read_graph(graph_path)
    return WorkspaceQuery(graph, root=root)

