    return (items, False)

@server.tool()
def entry_status(root: str='.') -> dict[str, Any]:
    """List workspace entries with language, type, and build status"""
    _s = time.monotonic()
    q = create_query(root)
    if q.graph.manifest is None:
        return {'entries': [], 'duration_ms': _duration(_s)}
    return {'entries': [{'name': e.name, 'language': e.language, 'type': e.type, 'path': e.path, 'build_status': e.build_status, 'symbol_count': e.symbol_count, 'call_count': e.call_count, 'route_count': e.route_count} for e in q.graph.manifest.entries], 'duration_ms': _duration(_s)}

@server.tool()
def query_symbols(pattern: str, kind: str | None=None, entry_kind: str | None=None, min_calls: int | None=None, max_calls: int | None=None, max_results: int=50, root: str='.') -> dict[str, Any]:
    """Search symbols by pattern (regex or substring) across all entries.
    Filters: kind (e.g. 'utility', '!utility'), entry_kind (e.g. 'library', '!library'),
    min_calls (exclude if fan-in >= N), max_calls (exclude if fan-in <= N)."""
    _s = time.monotonic()
    q = create_query(root)
    result = q.find_symbols(pattern, kind=kind, entry_kind=entry_kind, min_calls=min_calls, max_calls=max_calls, max_results=max_results)
    return {'items': result['items'], 'total': result['total'], 'truncated': result['truncated'], 'duration_ms': _duration(_s), 'load_ms': int(_last_load_ms), 'query_ms': _duration(_s) - int(_last_load_ms)}

def _summary_box(items: list[dict[str, Any]], start: float, group_key: str) -> dict[str, Any]:
    groups: dict[str, dict[str, Any]] = {}
    for item in items:
        key = item.get(group_key, '')
        entry = item.get('entry_name', '')
        composite = f'{entry}::{key}'
        if composite not in groups:
            groups[composite] = {group_key: key, 'entry_name': entry, 'call_count': 0, 'unique_files': set(), 'unique_callers': set()}
        groups[composite]['call_count'] += 1
        groups[composite]['unique_files'].add(item.get('file', ''))
        caller = item.get('caller') or item.get('callee')
        if caller:
            groups[composite]['unique_callers'].add(caller)
    result = []
    for g in groups.values():
        g['unique_files'] = len(g['unique_files'])
        g['unique_callers'] = len(g['unique_callers'])
        result.append(g)
    result.sort(key=lambda x: -x['call_count'])
    return {'items': result, 'total': len(groups), 'duration_ms': _duration(start), 'load_ms': int(_last_load_ms), 'query_ms': _duration(start) - int(_last_load_ms)}

@server.tool()
def callers(name: str, summary: bool=True, kind: str | None=None, entry_kind: str | None=None, min_calls: int | None=None, max_calls: int | None=None, max_results: int=50, root: str='.') -> dict[str, Any]:
    """Show who calls the given symbol.
    summary=True groups by caller name; summary=False returns raw edges.
    Filters: kind (e.g. '!utility'), entry_kind, min_calls, max_calls."""
    _s = time.monotonic()
    q = create_query(root)
    result = q.get_callers(name, kind=kind, entry_kind=entry_kind, min_calls=min_calls, max_calls=max_calls, max_results=None)
    items = result['items']
    raw_total = result['total']
    items, truncated = _truncate(items, max_results)
    if summary and items:
        return _summary_box(items, _s, 'caller')
    return {'items': items, 'total': raw_total, 'truncated': truncated, 'duration_ms': _duration(_s), 'load_ms': int(_last_load_ms), 'query_ms': _duration(_s) - int(_last_load_ms)}

@server.tool()
def routes(entry: str | None=None, type_filter: str | None=None, include_route_wrappers: bool=True, root: str='.') -> dict[str, Any]:
    """List HTTP routes across the workspace, optionally filtered.
    include_route_wrappers=True also detects calls to route_wrapper-classified symbols
    as synthetic route entries (mark via classify_symbol(kind='route_wrapper'))."""
    _s = time.monotonic()
    q = create_query(root)
    results = list(q.graph.routes)
    if entry:
        results = [r for r in results if r.get('entry_name') == entry]
    if type_filter:
        results = [r for r in results if r.get('type') == type_filter]
    if include_route_wrappers:
        wrapper_names = list(q.list_classifications(kind='route_wrapper').get('symbols', {}).keys())
        if wrapper_names:
            seen_calls: set[tuple[str, str, int]] = set()
            for call in q.graph.calls:
                craw = call.get('callee_raw', '')
                for wrapper in wrapper_names:
                    if wrapper not in craw:
                        continue
                    cid = call.get('caller_symbol_id', '')
                    lineno = call.get('line', 0)
                    k = (cid, craw, lineno)
                    if k in seen_calls:
                        continue
                    seen_calls.add(k)
                    caller_sym = q._symbols_by_id.get(cid)
                    caller_name = caller_sym.get('name', '') if caller_sym else '<module>'
                    results.append({'method': 'WRAPPER', 'path': f'[{craw}]', 'handler': caller_name, 'file': call.get('file', ''), 'line': lineno, 'entry_name': call.get('entry_name', ''), 'language': call.get('language', ''), 'type': call.get('type', '')})
    items = [{'method': r.get('method', ''), 'path': r.get('path', ''), 'handler': r.get('handler', ''), 'file': r.get('file', ''), 'line': r.get('line', 0), 'entry_name': r.get('entry_name', ''), 'language': r.get('language', ''), 'type': r.get('type', '')} for r in results]
    return _box(items, _s)

@server.tool()
def orphans(include_public: bool=False, skip_underscore: bool=True, exclude_type: str | None=None, kind: str | None=None, entry_kind: str | None=None, max_results: int=100, root: str='.') -> dict[str, Any]:
    """List unreachable symbols (dead code).
    skip_underscore=True filters private _methods (likely false positives).
    Filters: kind (e.g. '!utility'), entry_kind."""
    _s = time.monotonic()
    q = create_query(root)
    results = q.get_orphans(include_public=include_public, skip_underscore=skip_underscore)
    filtered = []
    for o in results:
        if exclude_type and o.get('type') == exclude_type:
            continue
        if kind:
            sym_class = q._sym_classification(o.get('name', ''))
            if kind.startswith('!'):
                if sym_class == kind[1:]:
                    continue
            elif sym_class != kind:
                continue
        if entry_kind:
            entry_class = q._entry_classification(o.get('entry_name', ''))
            if entry_kind.startswith('!'):
                if entry_class == entry_kind[1:]:
                    continue
            elif entry_class != entry_kind:
                continue
        filtered.append(o)
    items = [{'name': o.get('name', ''), 'kind': o.get('kind', ''), 'file': o.get('file', ''), 'line': o.get('line', 0), 'entry_name': o.get('entry_name', ''), 'language': o.get('language', ''), 'type': o.get('type', '')} for o in filtered]
    items, truncated = _truncate(items, max_results)
    result = _box(items, _s)
    result['truncated'] = truncated
    return result

