def _normalize_route_path(path: str) -> list[str]:
    parts = path.strip('/').split('/')
    result: list[str] = []
    for p in parts:
        if not p:
            continue
        is_param = p.startswith((':', '{', '<')) or p.endswith(('}', '>'))
        if is_param:
            result.append('*')
        else:
            result.append(p)
    return result

def _parse_url_static_segments(url: str) -> list[str]:
    if '://' in url:
        url = url.split('://', 1)[1]
        if '/' in url:
            url = url[url.index('/'):]
        else:
            return []
    if '?' in url:
        url = url.split('?', 1)[0]
    parts = url.strip('/').split('/')
    return [p for p in parts if p]

def _segments_match(url_segments: list[str], route_segments: list[str]) -> bool:
    if len(url_segments) != len(route_segments):
        return False
    for u, r in zip(url_segments, route_segments, strict=True):
        if r == '*':
            continue
        if u != r:
            return False
    return True

def _extract_http_method(http_call: dict[str, Any]) -> str:
    raw = http_call.get('method', 'GET')
    if not isinstance(raw, str) or not raw:
        return 'GET'
    return raw.upper()

def detect_cross_service_edges(unified: UnifiedGraph) -> list[dict[str, Any]]:
    entries: dict[str, list[dict[str, Any]]] = {}
    for call in unified.http_calls:
        entry_name = call.get('entry_name', '')
        entries.setdefault(entry_name, []).append(call)
    routes_by_entry: dict[str, list[dict[str, Any]]] = {}
    for route in unified.routes:
        entry_name = route.get('entry_name', '')
        routes_by_entry.setdefault(entry_name, []).append(route)
    edges: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str, str, int]] = set()
    for source_entry, calls in entries.items():
        for call in calls:
            method = _extract_http_method(call)
            url = call.get('url', '')
            call_segments = call.get('static_segments', [])
            parsed = call_segments if call_segments else _parse_url_static_segments(url)
            if not parsed:
                continue
            for target_entry, target_routes in routes_by_entry.items():
                if target_entry == source_entry:
                    continue
                for route in target_routes:
                    route_method = route.get('method', '').upper()
                    route_path = route.get('path', '')
                    route_segments = _normalize_route_path(route_path)
                    if not _segments_match(parsed, route_segments):
                        continue
                    confidence = 'high' if method == route_method else 'medium'
                    dedup_key = (source_entry, target_entry, method, route_path, call.get('source_line', 0))
                    if dedup_key in seen:
                        continue
                    seen.add(dedup_key)
                    edges.append({'source_entry': source_entry, 'source_file': call.get('source_file', ''), 'source_line': call.get('source_line', 0), 'source_symbol': call.get('function_name', ''), 'method': method, 'url_pattern': url, 'target_entry': target_entry, 'target_route_path': route_path, 'target_route_handler': route.get('handler', ''), 'confidence': confidence})
    return edges

def _get_plugins_from_config(root: str) -> list[str]:
    from codegraph.config import load_config
    config = load_config(root)
    return list(config.plugins)

def run_plugins(graph: UnifiedGraph, root: str) -> None:
    plugins = _get_plugins_from_config(root)
    if not plugins:
        return
    root_path = Path(root).resolve()
    for plugin_rel in plugins:
        plugin_path = (root_path / plugin_rel).resolve()
        if not plugin_path.exists():
            print(f'[codegraph] plugin not found: {plugin_path}', file=sys.stderr)
            continue
        try:
            spec = importlib.util.spec_from_file_location(f'_codegraph_plugin_{plugin_path.stem}', plugin_path)
            if spec is None or spec.loader is None:
                print(f'[codegraph] failed to load plugin: {plugin_path}', file=sys.stderr)
                continue
            mod = importlib.util.module_from_spec(spec)
            sys.modules[mod.__name__] = mod
            spec.loader.exec_module(mod)
            if not hasattr(mod, 'run'):
                print(f'[codegraph] plugin {plugin_path} has no run(graph) function', file=sys.stderr)
                continue
            mod.run(graph)
        except Exception:
            print(f'[codegraph] plugin {plugin_path} raised an error:', file=sys.stderr)
            traceback.print_exc(file=sys.stderr)

def graph_to_dict(graph: UnifiedGraph) -> dict[str, Any]:
    result: dict[str, Any] = {'schema_version': graph.schema_version, 'generated_at': graph.generated_at, 'workspace_root': graph.workspace_root}
    if graph.manifest is not None:
        result['manifest'] = _manifest_to_dict(graph.manifest)
    for field_name in ARRAY_FIELDS:
        items = getattr(graph, field_name, [])
        result[field_name] = [item for item in items]
    return result

def dict_to_graph(data: dict[str, Any]) -> UnifiedGraph:
    kwargs: dict[str, Any] = {'schema_version': data.get('schema_version', SCHEMA_VERSION), 'generated_at': data.get('generated_at', ''), 'workspace_root': data.get('workspace_root', '')}
    raw_manifest = data.get('manifest')
    if raw_manifest is not None:
        kwargs['manifest'] = _dict_to_manifest(raw_manifest)
    for field_name in ARRAY_FIELDS:
        kwargs[field_name] = data.get(field_name, [])
    return UnifiedGraph(**kwargs)

def serialize(graph: UnifiedGraph) -> str:
    if graph.schema_version != SCHEMA_VERSION:
        msg = f'Graph version mismatch: expected {SCHEMA_VERSION}, got {graph.schema_version}'
        raise ValueError(msg)
    data = graph_to_dict(graph)
    if HAS_ORJSON:
        return orjson.dumps(data, option=orjson.OPT_INDENT_2).decode()
    return json.dumps(data, indent=2)

def _ensure_fields(parsed: dict[str, Any]) -> None:
    for field_name in REQUIRED_FIELDS:
        if field_name not in parsed:
            msg = f'Missing required field: {field_name}'
            raise ValueError(msg)
    for field_name in ARRAY_FIELDS:
        if field_name in parsed and (not isinstance(parsed[field_name], list)):
            msg = f"Field '{field_name}' must be a list"
            raise ValueError(msg)

def deserialize(raw: str | bytes) -> UnifiedGraph:
    try:
        parsed = orjson.loads(raw) if HAS_ORJSON and isinstance(raw, bytes) else json.loads(raw)
    except (json.JSONDecodeError, ValueError) as e:
        msg = f'Invalid JSON: {e}'
        raise ValueError(msg) from e
    if not isinstance(parsed, dict):
        msg = 'Invalid graph structure: expected a JSON object'
        raise ValueError(msg)
    _ensure_fields(parsed)
    if parsed['schema_version'] != SCHEMA_VERSION:
        msg = f"Graph version mismatch: expected {SCHEMA_VERSION}, got {parsed['schema_version']}"
        raise ValueError(msg)
    return dict_to_graph(parsed)

def write_graph(graph: UnifiedGraph, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    data = graph_to_dict(graph)
    if HAS_ORJSON:
        path.write_bytes(orjson.dumps(data, option=orjson.OPT_INDENT_2))
    else:
        with open(path, 'w') as f:
            f.write(json.dumps(data, indent=2))

def write_manifest(manifest: Manifest, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    data = _manifest_to_dict(manifest)
    if HAS_ORJSON:
        path.write_bytes(orjson.dumps(data, option=orjson.OPT_INDENT_2))
    else:
        with open(path, 'w') as f:
            f.write(json.dumps(data, indent=2))

def read_graph(path: Path) -> UnifiedGraph:
    if HAS_ORJSON:
        return deserialize(path.read_bytes())
    with open(path) as f:
        return deserialize(f.read())

def _load_build_statuses(root_path: Path) -> dict[str, str]:
    manifest_path = root_path / '.codegraph' / 'manifest.json'
    if not manifest_path.exists():
        return {}
    try:
        data = json.loads(manifest_path.read_text())
        return {e['name']: e.get('build_status', 'unbuilt') for e in data.get('entries', [])}
    except (OSError, json.JSONDecodeError, ValueError):
        return {}

